--
-- Table structure for table `act_hi_procinst`
--

DROP TABLE IF EXISTS `act_hi_procinst`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `act_hi_procinst` (
  `ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `REV_` int DEFAULT '1',
  `PROC_INST_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `BUSINESS_KEY_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `PROC_DEF_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL,
  `START_TIME_` datetime(3) NOT NULL,
  `END_TIME_` datetime(3) DEFAULT NULL,
  `DURATION_` bigint DEFAULT NULL,
  `START_USER_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `START_ACT_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `END_ACT_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `SUPER_PROCESS_INSTANCE_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `DELETE_REASON_` varchar(4000) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `TENANT_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT '',
  `NAME_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `CALLBACK_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `CALLBACK_TYPE_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `REFERENCE_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `REFERENCE_TYPE_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `PROPAGATED_STAGE_INST_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `BUSINESS_STATUS_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `END_USER_ID_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `STATE_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `DUE_DATE_` datetime(3) DEFAULT NULL,
  `CLAIM_TIME_` datetime(3) DEFAULT NULL,
  `CLAIMED_BY_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL,
  `DEF_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT 'blade 业务定义ID(wf_definition.id)',
  `DATA_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '业务数据ID(表单数据主键)',
  `FORM_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '表单ID',
  `TITLE_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '业务标题',
  `IS_TEST_` tinyint DEFAULT '0' COMMENT '是否测试流程 0否1是',
  `BUSINESS_ID_` bigint DEFAULT NULL COMMENT 'blade 业务实例ID(原 wf_instance.id 雪花, 业务表 request_id 外键)',
  `STARTER_` bigint DEFAULT NULL COMMENT '发起人(原 wf_instance.starter)',
  `CURRENT_NODE_KEY_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '当前节点Key(advance 维护, 并行分支安全)',
  `URGENCY_` int DEFAULT '0' COMMENT '紧急程度 0/1/2',
  `BUSINESS_ROW_READY_` tinyint DEFAULT NULL COMMENT 'L3自检:业务行就绪 1/0/NULL',
  `REQUEST_ID_BOUND_` tinyint DEFAULT NULL COMMENT 'L3自检:request_id 回填 1/0/NULL',
  `ENGINE_DEPLOY_MATCHED_` tinyint DEFAULT NULL COMMENT 'L3自检:引擎latest==定义部署 1/0/NULL',
  `PARENT_ID_` bigint DEFAULT NULL COMMENT '父流程实例ID(子流程)',
  `TEST_DEPLOYMENT_ID_` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '测试临时部署ID(清理用)',
  `PENDING_STATUS_` int DEFAULT NULL COMMENT '期望终态intent 1通过/2不通过/3撤销/NULL',
  `DEF_KEY_` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin DEFAULT NULL COMMENT '引擎流程定义KEY（ACT_RE_PROCDEF.KEY_）；桥接业务defId与引擎版本组',
  PRIMARY KEY (`ID_`),
  UNIQUE KEY `PROC_INST_ID_` (`PROC_INST_ID_`),
  KEY `ACT_IDX_HI_PRO_INST_END` (`END_TIME_`),
  KEY `ACT_IDX_HI_PRO_I_BUSKEY` (`BUSINESS_KEY_`),
  KEY `ACT_IDX_HI_PRO_SUPER_PROCINST` (`SUPER_PROCESS_INSTANCE_ID_`),
  KEY `IDX_HI_PROC_TENANT_STATUS` (`TENANT_ID_`,`BUSINESS_STATUS_`),
  KEY `IDX_HI_PROC_DEF_DATA` (`DEF_ID_`,`DATA_ID_`),
  KEY `IDX_HI_PROC_TEST` (`TENANT_ID_`,`IS_TEST_`,`END_TIME_`),
  KEY `IDX_HI_PROC_BUSINESS_ID` (`BUSINESS_ID_`),
  KEY `IDX_HI_PROC_STARTER` (`TENANT_ID_`,`STARTER_`,`IS_TEST_`,`START_TIME_`),
  KEY `IDX_HI_PROC_FORM` (`TENANT_ID_`,`FORM_ID_`,`IS_TEST_`),
  KEY `IDX_HI_PROC_BIZKEY` (`TENANT_ID_`,`BUSINESS_KEY_`),
  KEY `IDX_HI_PROC_T_DEFKEY` (`TENANT_ID_`,`DEF_KEY_`),
  KEY `IDX_HI_PRO_T_DEFID` (`TENANT_ID_`,`DEF_ID_`),
  KEY `IDX_HI_PRO_T_DATAID` (`TENANT_ID_`,`DATA_ID_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_bin;
/*!40101 SET character_set_client = @saved_cs_client */;

