DROP TABLE IF EXISTS `blade_message_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blade_message_session` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(50) NOT NULL COMMENT '租户ID',
  `name` varchar(100) DEFAULT NULL COMMENT '群名称（两人会话可为空）',
  `type` int NOT NULL DEFAULT '1' COMMENT '会话类型 1=两人 2=群 3=系统通知（流程消息，每人一条）',
  `last_message` varchar(500) DEFAULT NULL COMMENT '最近一条消息摘要',
  `last_time` datetime DEFAULT NULL COMMENT '最近消息时间',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_user` bigint DEFAULT NULL COMMENT '更新人',
  `status` int DEFAULT NULL COMMENT '状态',
  `is_deleted` int DEFAULT NULL COMMENT '是否已删除',
  PRIMARY KEY (`id`),
  KEY `idx_blade_message_session_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息会话';
