DROP TABLE IF EXISTS `blade_portal_login_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blade_portal_login_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` varchar(12) DEFAULT '000000' COMMENT '租户ID',
  `template_name` varchar(128) NOT NULL COMMENT '模板名称',
  `template_type` varchar(64) DEFAULT 'default' COMMENT '模板类型标识',
  `background_config` text COMMENT '背景配置JSON {bgColor,bgImage}',
  `logo_config` text COMMENT 'Logo配置JSON {logoUrl,title}',
  `form_config` text COMMENT '登录框配置JSON',
  `qrcode_config` text COMMENT '二维码配置JSON',
  `copyright_config` text COMMENT '版权配置JSON',
  `is_current` int DEFAULT '0' COMMENT '是否当前启用（租户内唯一）',
  `open_timer` int DEFAULT '0' COMMENT '是否开启定时切换（0否 1是）',
  `timer_start` varchar(32) DEFAULT NULL COMMENT '定时开始 yyyy-MM-dd HH:mm:ss',
  `timer_end` varchar(32) DEFAULT NULL COMMENT '定时结束 yyyy-MM-dd HH:mm:ss',
  `is_deleted` int DEFAULT '0' COMMENT '是否删除',
  `status` int DEFAULT '1' COMMENT '状态',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_name` (`tenant_id`,`template_name`),
  KEY `idx_is_current` (`is_current`),
  KEY `idx_is_deleted` (`is_deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='登录前门户皮肤模板（对标泛微 SystemLoginTemplate）';
