  KEY `idx_member_level` (`member_level`),
  KEY `idx_member_status` (`member_status`),
  KEY `idx_blade_user_open_id` (`open_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户表';
