DROP TABLE IF EXISTS `doc_mould`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doc_mould` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(50) DEFAULT NULL COMMENT '租户ID',
  `mould_name` varchar(255) DEFAULT NULL COMMENT '模板名',
  `mould_type` int DEFAULT NULL COMMENT '模板类型 0HTML 2WORD 3EXCEL 4WPS',
  `is_default` int DEFAULT '0' COMMENT '是否默认',
  `image_file_id` bigint DEFAULT NULL COMMENT '模板内容文件ID',
  `mould_path` varchar(500) DEFAULT NULL COMMENT '模板路径',
  `create_user` bigint DEFAULT NULL,
  `create_dept` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_user` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `status` int DEFAULT '1',
  `is_deleted` int DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='显示模板';
/*!40101 SET character_set_client = @saved_cs_client */;

