/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `imagefile` (
  `imagefileid` bigint NOT NULL COMMENT '文件ID',
  `imagefilename` varchar(500) DEFAULT NULL COMMENT '原始文件名',
  `imagefiletype` varchar(100) DEFAULT NULL COMMENT '文件类型（MIME类型）',
  `imagefileused` int DEFAULT '1' COMMENT '是否使用（1=使用）',
  `filerealpath` varchar(1000) DEFAULT NULL COMMENT '文件真实存储路径',
  `iszip` int DEFAULT '0' COMMENT '是否压缩（0/1）',
  `isencrypt` int DEFAULT '0' COMMENT '是否加密（0/1）',
  `fileSize` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `isaesencrypt` int DEFAULT '0' COMMENT '是否AES加密（0/1）',
  `aescode` varchar(50) DEFAULT NULL COMMENT 'AES加密密钥',
  `TokenKey` varchar(100) DEFAULT NULL COMMENT 'OSS Token',
  `secretLevel` int DEFAULT '4' COMMENT '密级',
  `secretValidity` varchar(50) DEFAULT NULL COMMENT '密级有效期',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `downloads` int DEFAULT '0' COMMENT '下载次数',
  `miniimgpath` varchar(500) DEFAULT NULL COMMENT '缩略图路径',
  `imgsize` varchar(100) DEFAULT NULL COMMENT '缩略图大小',
  `isftp` varchar(10) DEFAULT NULL COMMENT '是否FTP存储',
  `ftpconfigid` int DEFAULT NULL COMMENT 'FTP配置ID',
  `storagestatus` varchar(50) DEFAULT NULL COMMENT '传输状态',
  `comefrom` varchar(100) DEFAULT NULL COMMENT '附件来源',
  `updatedat` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `createdat` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenantid` varchar(50) NOT NULL DEFAULT '' COMMENT '租户ID',
  PRIMARY KEY (`imagefileid`),
  KEY `idx_imagefile_used` (`imagefileused`),
  KEY `idx_imagefile_secret_level` (`secretLevel`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='附件文件表';
